// Sprint 46 — Server-side data loader for the human review workbook.
//
// Reads data/human-lemma-review-workbook.json (generated by
// scripts/extract-lemma-evidence.mjs) and provides typed access to the
// evidence for each of the 10 manual roots.
//
// SERVER-ONLY: reads from the filesystem. Never import from client components.

import path from "node:path";
import fs from "node:fs";

const DATA_DIR = path.join(process.cwd(), "data");
const WORKBOOK_PATH = path.join(DATA_DIR, "human-lemma-review-workbook.json");

/** One lemma entry in the workbook evidence. */
export interface WorkbookLemma {
  lemma: string;
  count: number;
  percentage: number;
  consonantallyCompatible: boolean;
}

/** One root entry in the workbook evidence. */
export interface WorkbookRoot {
  slug: string;
  title: string;
  arabicTitle: string;
  root: string;
  existingAllowlistNotes: string;
  polysemyConcerns: string[];
  totalWordRecords: number;
  distinctAyat: number;
  recordsWithLemma: number;
  recordsWithoutLemma: number;
  lemmaCoverage: number;
  lemmaDistribution: WorkbookLemma[];
  incompatibleLemmaCount: number;
  incompatibleLemmas: Array<{ lemma: string; count: number }>;
  sampleAyat: Array<{
    surah: number;
    ayah: number;
    token: string;
    lemma: string | null;
    wordPosition: number;
  }>;
}

/** The complete workbook shape. */
export interface ReviewWorkbook {
  generatedAt: string;
  generator: string;
  sourceDataset: string;
  purpose: string;
  instructions: string;
  roots: WorkbookRoot[];
}

/** Cache across HMR reloads. */
const cache = (globalThis as unknown as { __alhudaReviewWorkbook?: ReviewWorkbook | null })
  .__alhudaReviewWorkbook ?? undefined;

if (cache === undefined) {
  (globalThis as unknown as { __alhudaReviewWorkbook?: ReviewWorkbook | null }).__alhudaReviewWorkbook = null;
}

/**
 * Load the review workbook from disk.
 * Returns null if the file does not exist or cannot be parsed.
 */
export function loadReviewWorkbook(): ReviewWorkbook | null {
  const cached = (globalThis as unknown as { __alhudaReviewWorkbook?: ReviewWorkbook | null })
    .__alhudaReviewWorkbook;
  if (cached) return cached;

  if (!fs.existsSync(WORKBOOK_PATH)) {
    return null;
  }

  try {
    const raw = fs.readFileSync(WORKBOOK_PATH, "utf-8");
    const data = JSON.parse(raw) as ReviewWorkbook;
    if (!data || !Array.isArray(data.roots)) return null;
    (globalThis as unknown as { __alhudaReviewWorkbook?: ReviewWorkbook | null }).__alhudaReviewWorkbook = data;
    return data;
  } catch {
    return null;
  }
}

/**
 * Get a single root's evidence from the workbook.
 */
export function getWorkbookRoot(slug: string): WorkbookRoot | null {
  const wb = loadReviewWorkbook();
  if (!wb) return null;
  return wb.roots.find((r) => r.slug === slug) ?? null;
}

/**
 * Check if the workbook is available.
 */
export function isWorkbookAvailable(): boolean {
  return fs.existsSync(WORKBOOK_PATH);
}
